/**
 * A minimal PagerDuty REST client for write-backs (notes, incident updates).
 * Every credential defaults to a well-known env var / deployment secret and
 * is read per call, so a hosted deployment, which receives its secrets per
 * request, sees them.
 */
import { pagerDutySecretName, resolvePagerDutySecret } from "./secrets.js";
/**
 * API token: a REST API key (user or account level), or an OAuth access
 * token written as `Bearer <token>`.
 */
export const PAGERDUTY_TOKEN_ENV = "PAGERDUTY_TOKEN";
/** REST base override, e.g. `https://api.eu.pagerduty.com` for the EU service region. */
export const PAGERDUTY_API_BASE_URL_ENV = "PAGERDUTY_API_BASE_URL";
/** `From` email for write calls made with an account-level REST API key. */
export const PAGERDUTY_FROM_EMAIL_ENV = "PAGERDUTY_FROM_EMAIL";
export const PAGERDUTY_DEFAULT_API_BASE_URL = "https://api.pagerduty.com";
/**
 * The REST base for a call: the authored `apiBaseUrl`, else
 * `PAGERDUTY_API_BASE_URL`, else `https://api.pagerduty.com`.
 */
export function pagerDutyApiBaseUrl(apiBaseUrl) {
    return (apiBaseUrl ??
        resolvePagerDutySecret(undefined, PAGERDUTY_API_BASE_URL_ENV) ??
        PAGERDUTY_DEFAULT_API_BASE_URL).replace(/\/+$/, "");
}
/**
 * `Authorization` for a token: a value already written as `Bearer <token>`
 * (an OAuth access token) is sent as-is; anything else is a REST API key.
 */
export function pagerDutyAuthorizationHeader(token) {
    return /^bearer\s/i.test(token) ? token : `Token token=${token}`;
}
export class PagerDutyApiError extends Error {
    constructor(input) {
        super(`PagerDuty ${input.method} ${input.path} failed with ${input.status}`);
        this.name = "PagerDutyApiError";
        this.status = input.status;
        this.body = input.body;
    }
}
export function createPagerDutyClient(options = {}) {
    const request = async (input) => {
        const token = resolvePagerDutySecret(options.token, PAGERDUTY_TOKEN_ENV);
        if (token === undefined) {
            const name = pagerDutySecretName(options.token, PAGERDUTY_TOKEN_ENV) ?? PAGERDUTY_TOKEN_ENV;
            throw new Error(`PagerDuty API token is not set: set ${name} (\`agent-sdk secret set <slug> ${name}\`) or pass \`token\`.`);
        }
        const from = resolvePagerDutySecret(options.from, PAGERDUTY_FROM_EMAIL_ENV);
        const base = pagerDutyApiBaseUrl(options.apiBaseUrl);
        const headers = {
            Accept: "application/vnd.pagerduty+json;version=2",
            Authorization: pagerDutyAuthorizationHeader(token),
            "Content-Type": "application/json",
        };
        if (from !== undefined) {
            headers.From = from;
        }
        const response = await (options.fetch ?? fetch)(`${base}${input.path}`, {
            method: input.method,
            headers,
            body: input.body === undefined ? undefined : JSON.stringify(input.body),
        });
        const text = await response.text();
        if (!response.ok) {
            throw new PagerDutyApiError({
                method: input.method,
                path: input.path,
                status: response.status,
                body: text,
            });
        }
        // oxlint-disable-next-line typescript/no-unsafe-type-assertion -- the caller names the JSON shape; this helper cannot validate an arbitrary T
        return (text === "" ? undefined : JSON.parse(text));
    };
    return {
        request,
        addNote: async ({ incidentId, content }) => {
            const created = await request({
                method: "POST",
                path: `/incidents/${encodeURIComponent(incidentId)}/notes`,
                body: { note: { content } },
            });
            return created.note;
        },
        getIncident: async (incidentId) => {
            const found = await request({
                method: "GET",
                path: `/incidents/${encodeURIComponent(incidentId)}`,
            });
            return found.incident;
        },
    };
}
/** The REST client for a channel's credentials, each falling back to its well-known secret. */
export function pagerDutyChannelClient(options) {
    return createPagerDutyClient({
        token: options.token,
        from: options.from,
        apiBaseUrl: options.apiBaseUrl,
    });
}
